package com.basiclab.iot.transform.runtime.service; import com.basiclab.iot.transform.core.domain.Contract; import com.basiclab.iot.transform.runtime.dal.TransformRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class ContractService { private final TransformRepository repository; public ContractService(TransformRepository repository){this.repository=repository;} public Collection<Contract> list(){return repository.listContracts();} public Contract get(String id){return repository.contract(id);} }